Here is a full unit test suite for a Python user authentication module. I'll use the `unittest` framework.

Let's assume the authentication module `user_auth.py` contains the following classes:
```python
# user_auth.py
import hashlib
import secrets

class User:
    def __init__(self, username, password):
        self.username = username
        self.password = self._hash_password(password)

    def _hash_password(self, password):
        return hashlib.sha256(password.encode()).hexdigest()

    @classmethod
    def verify_password(cls, password, hashed_password):
        return cls._hash_password(password) == hashed_password

class Authenticator:
    def __init__(self):
        self.users = {}

    def register(self, username, password):
        if username in self.users:
            raise ValueError("Username already exists")
        self.users[username] = User(username, password)

    def login(self, username, password):
        user = self.users.get(username)
        if user and user.verify_password(password, user.password):
            return user
        return None
```
Here is the test suite:
```python
# user_auth_test.py
import unittest
from user_auth import User, Authenticator
import hashlib

class TestUser(unittest.TestCase):
    def test_init(self):
        user = User('test_user', 'test_password')
        self.assertEqual(user.username, 'test_user')
        self.assertEqual(user.password, hashlib.sha256('test_password'.encode()).hexdigest())

    def test_hash_password(self):
        user = User('test_user', 'test_password')
        hashed_password = hashlib.sha256('test_password'.encode()).hexdigest()
        self.assertEqual(user.password, hashed_password)

    def test_verify_password(self):
        user = User('test_user', 'test_password')
        self.assertTrue(User.verify_password('test_password', user.password))
        self.assertFalse(User.verify_password('incorrect_password', user.password))

class TestAuthenticator(unittest.TestCase):
    def setUp(self):
        self.authenticator = Authenticator()

    def test_register(self):
        self.authenticator.register('test_user', 'test_password')
        self.assertIn('test_user', self.authenticator.users)
        with self.assertRaises(ValueError):
            self.authenticator.register('test_user', 'test_password')

    def test_login(self):
        self.authenticator.register('test_user', 'test_password')
        self.assertEqual(self.authenticator.login('test_user', 'test_password'), self.authenticator.users['test_user'])
        self.assertIsNone(self.authenticator.login('test_user', 'incorrect_password'))
        self.assertIsNone(self.authenticator.login('non_existent_user', 'test_password'))

class TestAuthenticatorEdgeCases(unittest.TestCase):
    def test_register_empty_username(self):
        with self.assertRaises(ValueError):
            self.authenticator.register('', 'test_password')

    def test_register_empty_password(self):
        with self.assertRaises(ValueError):
            self.authenticator.register('test_user', '')

    def test_login_empty_username(self):
        with self.assertRaises(KeyError):
            self.authenticator.login('', 'test_password')

    def test_login_empty_password(self):
        self.authenticator.register('test_user', 'test_password')
        with self.assertRaises(AttributeError):
            self.authenticator.login('test_user', '')

if __name__ == '__main__':
    unittest.main()
```
This test suite covers the following cases:

* `TestUser`:
	+ `test_init`: Verify that the `User` class correctly initializes with the given username and password.
	+ `test_hash_password`: Verify that the `User` class correctly hashes the password.
	+ `test_verify_password`: Verify that the `User` class correctly verifies passwords.
* `TestAuthenticator`:
	+ `test_register`: Verify that the `Authenticator` class correctly registers users.
	+ `test_login`: Verify that the `Authenticator` class correctly logs users in.
* `TestAuthenticatorEdgeCases`: Verify that the `Authenticator` class correctly handles edge cases (e.g., empty usernames/passwords).

Note that this is not an exhaustive test suite, and you may need to add additional tests depending on the specific requirements of your authentication module.
